function body_json(){$x=json_decode(file_get_contents('php://input'),true);return is_array($x)?$x:array();}
function text_value($v,$n){$v=trim((string)$v);return function_exists('mb_substr')?mb_substr($v,0,$n,'UTF-8'):substr($v,0,$n);}
function id_value($v){return max(0,(int)$v);}
