 if($_SERVER['REQUEST_METHOD']==='GET'&&$action==='overview'){
  mtpc_require_permission('students.read');$total=(int)$pdo->query('SELECT COUNT(*) FROM students')->fetchColumn();$today=date('Y-m-d');$s=$pdo->prepare("SELECT COUNT(*) FROM attendance_records r JOIN attendance_sessions s ON s.id=r.session_id WHERE s.session_date=:d AND r.status IN ('absent','late')");$s->execute(array(':d'=>$today));$attendanceWarnings=(int)$s->fetchColumn();$fees=array('due'=>0,'paid'=>0,'debt'=>0);if(mtpc_has_permission('finance.read')){$row=$pdo->query("SELECT COALESCE(SUM(sf.amount_due),0) due,COALESCE(SUM(p.paid),0) paid FROM student_fees sf LEFT JOIN (SELECT student_fee_id,SUM(amount) paid FROM fee_payments GROUP BY student_fee_id)p ON p.student_fee_id=sf.id")->fetch();$fees=array('due'=>(float)$row['due'],'paid'=>(float)$row['paid'],'debt'=>max(0,(float)$row['due']-(float)$row['paid']));}mtpc_students_response(200,array('ok'=>true,'summary'=>array('students'=>$total,'attendance_warnings'=>$attendanceWarnings,'finance'=>$fees)));
 }
 if($_SERVER['REQUEST_METHOD']==='GET'&&$action==='attendance_sessions'){
  mtpc_require_permission('attendance.read');$from=isset($_GET['from'])?text_value($_GET['from'],10):date('Y-m-01');$to=isset($_GET['to'])?text_value($_GET['to'],10):date('Y-m-d');$class=isset($_GET['class_name'])?text_value($_GET['class_name'],100):'';$sql="SELECT s.*,COUNT(r.id) total,SUM(r.status='present') present_count,SUM(r.status='late') late_count,SUM(r.status='excused') excused_count,SUM(r.status='absent') absent_count FROM attendance_sessions s LEFT JOIN attendance_records r ON r.session_id=s.id WHERE s.session_date BETWEEN :f AND :t";$p=array(':f'=>$from,':t'=>$to);if($class!==''){$sql.=' AND s.class_name=:c';$p[':c']=$class;}$sql.=' GROUP BY s.id ORDER BY s.session_date DESC,s.id DESC LIMIT 100';$st=$pdo->prepare($sql);$st->execute($p);mtpc_students_response(200,array('ok'=>true,'sessions'=>$st->fetchAll()));
 }
 if($_SERVER['REQUEST_METHOD']==='GET'&&$action==='attendance_roster'){
  mtpc_require_permission('attendance.read');$id=id_value(isset($_GET['session_id'])?$_GET['session_id']:0);$st=$pdo->prepare('SELECT s.id,s.student_code,s.full_name,s.class_name,COALESCE(r.status,"present") status,r.note FROM attendance_sessions a JOIN students s ON s.class_name=a.class_name LEFT JOIN attendance_records r ON r.session_id=a.id AND r.student_id=s.id WHERE a.id=:id ORDER BY s.full_name');$st->execute(array(':id'=>$id));mtpc_students_response(200,array('ok'=>true,'records'=>$st->fetchAll()));
