 if($_SERVER['REQUEST_METHOD']==='GET'&&$action==='attendance_alerts'){
  mtpc_require_permission('attendance.read');$days=isset($_GET['days'])?max(7,min(180,(int)$_GET['days'])):30;$threshold=isset($_GET['threshold'])?max(1,min(30,(int)$_GET['threshold'])):3;$st=$pdo->prepare("SELECT s.id,s.student_code,s.full_name,s.class_name,s.program_name,SUM(r.status='absent') absent_count,SUM(r.status='late') late_count,SUM(r.status='excused') excused_count,ROUND(SUM(r.status='absent')+SUM(r.status='late')*.5,1) warning_score FROM students s JOIN attendance_records r ON r.student_id=s.id JOIN attendance_sessions a ON a.id=r.session_id WHERE a.session_date>=DATE_SUB(CURDATE(),INTERVAL ".$days." DAY) GROUP BY s.id HAVING warning_score>=:threshold ORDER BY warning_score DESC");$st->execute(array(':threshold'=>$threshold));mtpc_students_response(200,array('ok'=>true,'days'=>$days,'threshold'=>$threshold,'alerts'=>$st->fetchAll()));
