 if($_SERVER['REQUEST_METHOD']==='GET'&&$action==='fees'){
  mtpc_require_permission('finance.read');$q=isset($_GET['q'])?text_value($_GET['q'],120):'';$status=isset($_GET['status'])?text_value($_GET['status'],20):'';$sql='SELECT sf.id,s.student_code,s.full_name,s.class_name,f.name fee_name,f.due_date,sf.original_amount,sf.discount_amount,sf.amount_due,COALESCE(SUM(p.amount),0) paid_amount,GREATEST(sf.amount_due-COALESCE(SUM(p.amount),0),0) debt_amount,sf.status FROM student_fees sf JOIN students s ON s.id=sf.student_id JOIN fee_items f ON f.id=sf.fee_item_id LEFT JOIN fee_payments p ON p.student_fee_id=sf.id WHERE 1=1';$p=array();if($q!==''){$sql.=' AND (s.student_code LIKE :q OR s.full_name LIKE :q OR s.class_name LIKE :q)';$p[':q']='%'.$q.'%';}if($status!==''){$sql.=' AND sf.status=:status';$p[':status']=$status;}$sql.=' GROUP BY sf.id ORDER BY f.due_date DESC,s.full_name LIMIT 200';$st=$pdo->prepare($sql);$st->execute($p);mtpc_students_response(200,array('ok'=>true,'fees'=>$st->fetchAll()));
 }
