 $b=body_json();
 if($action==='create_attendance_session'){
  mtpc_require_permission('attendance.write');$class=text_value(isset($b['class_name'])?$b['class_name']:'',100);$subject=text_value(isset($b['subject_name'])?$b['subject_name']:'',150);$date=text_value(isset($b['session_date'])?$b['session_date']:'',10);if($class===''||$subject===''||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))mtpc_students_response(422,array('ok'=>false,'error'=>'Cần lớp, môn và ngày học hợp lệ.'));$st=$pdo->prepare('INSERT INTO attendance_sessions(class_name,subject_name,session_date,period_label,teacher_username,note) VALUES(:c,:s,:d,:p,:u,:n)');$st->execute(array(':c'=>$class,':s'=>$subject,':d'=>$date,':p'=>text_value(isset($b['period_label'])?$b['period_label']:'',50),':u'=>$mtpcActor['username'],':n'=>text_value(isset($b['note'])?$b['note']:'',500)));$id=$pdo->lastInsertId();mtpc_audit('attendance.session.create','attendance_session',$id,null,array('class_name'=>$class,'subject_name'=>$subject,'session_date'=>$date));mtpc_students_response(201,array('ok'=>true,'id'=>$id,'message'=>'Đã tạo buổi điểm danh.'));
 }
 if($action==='mark_attendance'){
  mtpc_require_permission('attendance.write');$session=id_value(isset($b['session_id'])?$b['session_id']:0);$records=isset($b['records'])&&is_array($b['records'])?$b['records']:array();if(!$session||!count($records))mtpc_students_response(422,array('ok'=>false,'error'=>'Thiếu buổi học hoặc danh sách điểm danh.'));$allowed=array('present','late','excused','absent');$pdo->beginTransaction();$st=$pdo->prepare('INSERT INTO attendance_records(session_id,student_id,status,note,marked_by) VALUES(:session,:student,:status,:note,:actor) ON DUPLICATE KEY UPDATE status=VALUES(status),note=VALUES(note),marked_by=VALUES(marked_by)');foreach($records as$r){$status=isset($r['status'])?(string)$r['status']:'present';if(!in_array($status,$allowed,true))$status='present';$st->execute(array(':session'=>$session,':student'=>id_value(isset($r['student_id'])?$r['student_id']:0),':status'=>$status,':note'=>text_value(isset($r['note'])?$r['note']:'',500),':actor'=>$mtpcActor['username']));}$pdo->commit();mtpc_audit('attendance.mark','attendance_session',$session,null,array('record_count'=>count($records)));mtpc_students_response(200,array('ok'=>true,'message'=>'Đã lưu điểm danh.','count'=>count($records)));
 }
 if($action==='assign_fee'){
  mtpc_require_permission('finance.write');$student=id_value(isset($b['student_id'])?$b['student_id']:0);$name=text_value(isset($b['fee_name'])?$b['fee_name']:'',150);$amount=max(0,(float)(isset($b['amount'])?$b['amount']:0));$discount=max(0,(float)(isset($b['discount_amount'])?$b['discount_amount']:0));if(!$student||$name===''||$amount<=0||$discount>$amount)mtpc_students_response(422,array('ok'=>false,'error'=>'Thông tin khoản thu không hợp lệ.'));$code='FEE-'.date('YmdHis').'-'.substr(md5(uniqid('',true)),0,5);$pdo->beginTransaction();$st=$pdo->prepare('INSERT INTO fee_items(code,name,amount,due_date) VALUES(:c,:n,:a,:d)');$st->execute(array(':c'=>$code,':n'=>$name,':a'=>$amount,':d'=>!empty($b['due_date'])?$b['due_date']:null));$feeItem=$pdo->lastInsertId();$due=$amount-$discount;$st=$pdo->prepare('INSERT INTO student_fees(student_id,fee_item_id,original_amount,discount_amount,discount_reason,amount_due,status,created_by) VALUES(:s,:f,:o,:d,:r,:due,:status,:u)');$st->execute(array(':s'=>$student,':f'=>$feeItem,':o'=>$amount,':d'=>$discount,':r'=>text_value(isset($b['discount_reason'])?$b['discount_reason']:'',500),':due'=>$due,':status'=>$due==0?'waived':'unpaid',':u'=>$mtpcActor['username']));$id=$pdo->lastInsertId();$pdo->commit();mtpc_audit('fee.assign','student_fee',$id,null,array('student_id'=>$student,'amount_due'=>$due));mtpc_students_response(201,array('ok'=>true,'id'=>$id,'message'=>'Đã tạo khoản thu.'));
 }
 if($action==='record_payment'){
  mtpc_require_permission('finance.write');$fee=id_value(isset($b['student_fee_id'])?$b['student_fee_id']:0);$amount=max(0,(float)(isset($b['amount'])?$b['amount']:0));if(!$fee||$amount<=0)mtpc_students_response(422,array('ok'=>false,'error'=>'Khoản thu hoặc số tiền không hợp lệ.'));$st=$pdo->prepare('SELECT sf.amount_due,COALESCE(SUM(p.amount),0) paid FROM student_fees sf LEFT JOIN fee_payments p ON p.student_fee_id=sf.id WHERE sf.id=:id GROUP BY sf.id');$st->execute(array(':id'=>$fee));$row=$st->fetch();if(!$row)mtpc_students_response(404,array('ok'=>false,'error'=>'Không tìm thấy khoản thu.'));$remaining=(float)$row['amount_due']-(float)$row['paid'];if($amount>$remaining)mtpc_students_response(422,array('ok'=>false,'error'=>'Số tiền vượt quá công nợ còn lại.'));$receipt='MTPC-'.date('Ymd-His').'-'.substr(md5(uniqid('',true)),0,4);$pdo->beginTransaction();$st=$pdo->prepare('INSERT INTO fee_payments(student_fee_id,amount,payment_method,reference_code,receipt_no,paid_at,note,received_by) VALUES(:f,:a,:m,:r,:no,NOW(),:n,:u)');$st->execute(array(':f'=>$fee,':a'=>$amount,':m'=>text_value(isset($b['payment_method'])?$b['payment_method']:'Tiền mặt',40),':r'=>text_value(isset($b['reference_code'])?$b['reference_code']:'',100),':no'=>$receipt,':n'=>text_value(isset($b['note'])?$b['note']:'',500),':u'=>$mtpcActor['username']));$status=$amount==$remaining?'paid':'partial';$st=$pdo->prepare('UPDATE student_fees SET status=:s WHERE id=:id');$st->execute(array(':s'=>$status,':id'=>$fee));$pdo->commit();mtpc_audit('fee.payment','student_fee',$fee,null,array('amount'=>$amount,'receipt_no'=>$receipt));mtpc_students_response(201,array('ok'=>true,'receipt_no'=>$receipt,'message'=>'Đã ghi nhận thanh toán.'));
 }
 if($action==='upsert_user'){
