 }
 if($action==='upsert_academic'){
  mtpc_require_permission('academic.write');$student=id_value(isset($b['student_id'])?$b['student_id']:0);$semester=id_value(isset($b['semester_id'])?$b['semester_id']:0);$subject=id_value(isset($b['subject_id'])?$b['subject_id']:0);if(!$student||!$semester||!$subject)mtpc_students_response(422,array('ok'=>false,'error'=>'Thiếu sinh viên, học kỳ hoặc môn học.'));$process=isset($b['process_score'])&&$b['process_score']!==''?(float)$b['process_score']:null;$exam=isset($b['exam_score'])&&$b['exam_score']!==''?(float)$b['exam_score']:null;$final=isset($b['final_score'])&&$b['final_score']!==''?(float)$b['final_score']:null;foreach(array($process,$exam,$final) as$score)if($score!==null&&($score<0||$score>10))mtpc_students_response(422,array('ok'=>false,'error'=>'Điểm phải nằm trong khoảng 0–10.'));$result=$final===null?'studying':($final>=5?'passed':'failed');$st=$pdo->prepare('INSERT INTO academic_results(student_id,semester_id,subject_id,process_score,exam_score,final_score,letter_grade,result,updated_by) VALUES(:student,:semester,:subject,:process,:exam,:final,:letter,:result,:actor) ON DUPLICATE KEY UPDATE process_score=VALUES(process_score),exam_score=VALUES(exam_score),final_score=VALUES(final_score),letter_grade=VALUES(letter_grade),result=VALUES(result),updated_by=VALUES(updated_by)');$st->execute(array(':student'=>$student,':semester'=>$semester,':subject'=>$subject,':process'=>$process,':exam'=>$exam,':final'=>$final,':letter'=>text_value(isset($b['letter_grade'])?$b['letter_grade']:'',5),':result'=>$result,':actor'=>$mtpcActor['username']));mtpc_audit('academic.upsert','student',$student,null,array('semester_id'=>$semester,'subject_id'=>$subject,'final_score'=>$final));mtpc_students_response(200,array('ok'=>true,'message'=>'Đã cập nhật kết quả học tập.'));
 }
